        # Invariants I1-I3: every transaction has at least two non-zero legs in
        # the book's currency, summing to exactly zero. Deferred to COMMIT so a
        # transaction can be written row by row; post_transaction() also runs
        # them immediately (SET CONSTRAINTS ... IMMEDIATE) right after writing.
        migrations.RunSQL(
            sql="""
            CREATE FUNCTION ledger_check_transaction_balanced() RETURNS trigger
            LANGUAGE plpgsql AS $$
            DECLARE
                tx_id uuid;
                leg_count bigint;
                leg_sum numeric;
                wrong_currency bigint;
                zero_legs bigint;
            BEGIN
                IF TG_TABLE_NAME = 'ledger_entry' THEN
                    tx_id := NEW.transaction_id;
                ELSE
                    tx_id := NEW.id;
                END IF;
                SELECT count(e.id),
                       coalesce(sum(e.amount), 0),
                       count(e.id) FILTER (WHERE e.amount_currency <> b.currency),
                       count(e.id) FILTER (WHERE e.amount = 0)
                  INTO leg_count, leg_sum, wrong_currency, zero_legs
                  FROM ledger_transaction t
                  JOIN ledger_book b ON b.id = t.book_id
                  LEFT JOIN ledger_entry e ON e.transaction_id = t.id
                 WHERE t.id = tx_id;
                IF leg_count < 2 THEN
                    RAISE EXCEPTION 'ledger transaction % has % legs, at least 2 are required',
                        tx_id, leg_count USING ERRCODE = 'check_violation';
                END IF;
                IF leg_sum <> 0 THEN
                    RAISE EXCEPTION 'ledger transaction % is unbalanced: legs sum to %',
                        tx_id, leg_sum USING ERRCODE = 'check_violation';
                END IF;
                IF wrong_currency > 0 THEN
                    RAISE EXCEPTION 'ledger transaction % has legs in a currency other than its book''s',
                        tx_id USING ERRCODE = 'check_violation';
                END IF;
                IF zero_legs > 0 THEN
                    RAISE EXCEPTION 'ledger transaction % has zero-amount legs',
                        tx_id USING ERRCODE = 'check_violation';
                END IF;
                RETURN NULL;
            END $$;

            CREATE CONSTRAINT TRIGGER ledger_entry_balanced
                AFTER INSERT OR UPDATE ON ledger_entry
                DEFERRABLE INITIALLY DEFERRED
                FOR EACH ROW EXECUTE FUNCTION ledger_check_transaction_balanced();

            CREATE CONSTRAINT TRIGGER ledger_transaction_balanced
                AFTER INSERT ON ledger_transaction
                DEFERRABLE INITIALLY DEFERRED
                FOR EACH ROW EXECUTE FUNCTION ledger_check_transaction_balanced();
            """,
            reverse_sql="""
            DROP TRIGGER ledger_transaction_balanced ON ledger_transaction;
            DROP TRIGGER ledger_entry_balanced ON ledger_entry;
            DROP FUNCTION ledger_check_transaction_balanced();
            """,
        ),
        # Invariant I4: posted rows are append-only, enforced below the ORM too.
        # TRUNCATE (used to flush test databases) fires no row triggers.
        migrations.RunSQL(
            sql="""
            CREATE FUNCTION ledger_forbid_change() RETURNS trigger
            LANGUAGE plpgsql AS $$
            BEGIN
                RAISE EXCEPTION 'ledger rows are append-only: % on % refused',
                    TG_OP, TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
            END $$;

            CREATE TRIGGER ledger_transaction_append_only
                BEFORE UPDATE OR DELETE ON ledger_transaction
                FOR EACH ROW EXECUTE FUNCTION ledger_forbid_change();

            CREATE TRIGGER ledger_entry_append_only
                BEFORE UPDATE OR DELETE ON ledger_entry
                FOR EACH ROW EXECUTE FUNCTION ledger_forbid_change();
            """,
            reverse_sql="""
            DROP TRIGGER ledger_entry_append_only ON ledger_entry;
            DROP TRIGGER ledger_transaction_append_only ON ledger_transaction;
            DROP FUNCTION ledger_forbid_change();
            """,
        ),
